/**
 * Client-side row identity used by the Component Attributes grid. Its rows are
 * created inline, before the server assigns an id.
 */
export type Row = Record<string, unknown>

/**
 * Client ids are prefixed so the grid can tell a new row from a saved one
 * without asking the parent. Generated by `createClientId(SAVE_GRID_NEW_PREFIX)`.
 */
export const SAVE_GRID_NEW_PREFIX = 'new_'

export function isSaveGridNewRow(row: Row) {
  const id = String(row.id ?? '')
  return !id || id.startsWith(SAVE_GRID_NEW_PREFIX)
}
